// One-shot scaffolder for the reverse-relation and routing fields.
// Kept in the repo so the generated files can be regenerated verbatim.
//
//   node scripts/generate-relation-fields.mjs

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

const header = `// GENERATED by scripts/generate-relation-fields.mjs — safe to edit by hand
// afterwards; re-running overwrites.
`;

const reverseRelation = ({
  fieldId,
  onObject,
  name,
  label,
  icon,
  targetObject,
  targetField,
  comment,
}) => `${header}
import {
  defineField,
  FieldType,
  RelationType,${onObject.standard ? '\n  STANDARD_OBJECT_UNIVERSAL_IDENTIFIERS,' : ''}
} from 'twenty-sdk/define';

import {
${[fieldId, targetObject.const, targetField]
  .filter(Boolean)
  .concat(onObject.standard ? [] : [onObject.const])
  .filter((value, index, all) => all.indexOf(value) === index)
  .sort()
  .map((name) => `  ${name},`)
  .join('\n')}
} from 'src/constants/universal-identifiers';
${comment ? `\n// ${comment}\n` : ''}
export default defineField({
  universalIdentifier: ${fieldId},
  objectUniversalIdentifier: ${
    onObject.standard
      ? `STANDARD_OBJECT_UNIVERSAL_IDENTIFIERS.${onObject.which ?? 'workspaceMember'}.universalIdentifier`
      : onObject.const
  },
  type: FieldType.RELATION,
  name: '${name}',
  label: '${label}',
  icon: '${icon}',
  isNullable: true,
  relationTargetObjectMetadataUniversalIdentifier: ${targetObject.const},
  relationTargetFieldMetadataUniversalIdentifier: ${targetField},
  universalSettings: { relationType: RelationType.ONE_TO_MANY },
});
`;

const scalarOnStandard = ({ fieldId, name, label, icon, type, description, extra = '', which = 'workspaceMember', comment }) =>
  `${header}
import {
  defineField,
  FieldType,
  STANDARD_OBJECT_UNIVERSAL_IDENTIFIERS,
} from 'twenty-sdk/define';

import { ${fieldId} } from 'src/constants/universal-identifiers';

${comment ?? `// Routing attribute read by the lv-assignment engine. Maintained by an admin on
// the team member's own record, so routing can change without a deploy.`}

export default defineField({
  universalIdentifier: ${fieldId},
  objectUniversalIdentifier:
    STANDARD_OBJECT_UNIVERSAL_IDENTIFIERS.${which}.universalIdentifier,
  type: FieldType.${type},
  name: '${name}',
  label: '${label}',
  description: '${description}',
  icon: '${icon}',
  isNullable: true,${extra}
});
`;

const MEMBER = { standard: true };

const LEAD = { const: 'LEAD_OBJECT_ID' };
const INTERACTION = { const: 'INTERACTION_OBJECT_ID' };
const HISTORY = { const: 'ASSIGNMENT_HISTORY_OBJECT_ID' };
const RULE = { const: 'ASSIGNMENT_RULE_OBJECT_ID' };
const NOTIFICATION = { const: 'NOTIFICATION_OBJECT_ID' };
const ONBOARDING = { const: 'ONBOARDING_OBJECT_ID' };
const ONBOARDING_DOC = { const: 'DOC_OBJECT_ID' };

const files = [
  // --- reverse relations ---------------------------------------------------
  [
    'src/modules/lv-core/fields/leads-on-workspace-member.field.ts',
    reverseRelation({
      fieldId: 'LEADS_ON_WORKSPACE_MEMBER_FIELD_ID',
      onObject: MEMBER,
      name: 'lvLeads',
      label: 'Leads',
      icon: 'IconUserSearch',
      targetObject: LEAD,
      targetField: 'LEAD_OWNER_FIELD_ID',
      comment:
        'Every lead this member owns. Drives the workload count the assignment engine balances on.',
    }),
  ],
  [
    'src/modules/lv-assignment/fields/assignment-histories-on-lead.field.ts',
    reverseRelation({
      fieldId: 'ASSIGNMENT_HISTORY_ON_LEAD_FIELD_ID',
      onObject: LEAD,
      name: 'assignmentHistory',
      label: 'Assignment history',
      icon: 'IconHistory',
      targetObject: HISTORY,
      targetField: 'ASSIGNMENT_HISTORY_LEAD_FIELD_ID',
    }),
  ],
  [
    'src/modules/lv-assignment/fields/assignment-history-from-on-member.field.ts',
    reverseRelation({
      fieldId: 'ASSIGNMENT_HISTORY_FROM_ON_MEMBER_FIELD_ID',
      onObject: MEMBER,
      name: 'lvAssignmentsGivenAway',
      label: 'Leads transferred away',
      icon: 'IconUserMinus',
      targetObject: HISTORY,
      targetField: 'ASSIGNMENT_HISTORY_FROM_FIELD_ID',
    }),
  ],
  [
    'src/modules/lv-assignment/fields/assignment-history-to-on-member.field.ts',
    reverseRelation({
      fieldId: 'ASSIGNMENT_HISTORY_TO_ON_MEMBER_FIELD_ID',
      onObject: MEMBER,
      name: 'lvAssignmentsReceived',
      label: 'Leads received',
      icon: 'IconUserPlus',
      targetObject: HISTORY,
      targetField: 'ASSIGNMENT_HISTORY_TO_FIELD_ID',
    }),
  ],
  [
    'src/modules/lv-assignment/fields/assignment-rules-on-member.field.ts',
    reverseRelation({
      fieldId: 'ASSIGNMENT_RULES_ON_MEMBER_FIELD_ID',
      onObject: MEMBER,
      name: 'lvAssignmentRules',
      label: 'Assignment rules',
      icon: 'IconRouteSquare',
      targetObject: RULE,
      targetField: 'ASSIGNMENT_RULE_ASSIGNEE_FIELD_ID',
    }),
  ],
  [
    'src/modules/lv-notifications/fields/notifications-on-member.field.ts',
    reverseRelation({
      fieldId: 'NOTIFICATIONS_ON_MEMBER_FIELD_ID',
      onObject: MEMBER,
      name: 'lvNotifications',
      label: 'Notifications',
      icon: 'IconBell',
      targetObject: NOTIFICATION,
      targetField: 'NOTIFICATION_RECIPIENT_FIELD_ID',
    }),
  ],
  [
    'src/modules/lv-interactions/fields/interactions-on-lead.field.ts',
    reverseRelation({
      fieldId: 'INTERACTIONS_ON_LEAD_ID',
      onObject: LEAD,
      name: 'interactions',
      label: 'Interactions',
      icon: 'IconMessageDots',
      targetObject: INTERACTION,
      targetField: 'INTERACTION_LEAD_ID',
      comment:
        'The relationship history on the Lead Profile: every recorded contact, newest first.',
    }),
  ],
  [
    'src/modules/lv-interactions/fields/interactions-on-member.field.ts',
    reverseRelation({
      fieldId: 'INTERACTIONS_ON_MEMBER_ID',
      onObject: MEMBER,
      name: 'lvInteractions',
      label: 'Interactions logged',
      icon: 'IconMessageDots',
      targetObject: INTERACTION,
      targetField: 'INTERACTION_ACTOR_ID',
    }),
  ],
  [
    'src/modules/lv-onboarding/fields/onboardings-on-lead.field.ts',
    reverseRelation({
      fieldId: 'ONBOARDINGS_ON_LEAD_ID',
      onObject: LEAD,
      name: 'onboardings',
      label: 'Partner onboarding',
      icon: 'IconRoute',
      targetObject: ONBOARDING,
      targetField: 'ONBOARDING_LEAD_ID',
      comment:
        'A lead may onboard more than once — a rejected partner can reapply, and the earlier attempt stays as history.',
    }),
  ],
  [
    'src/modules/lv-onboarding/fields/onboardings-on-member.field.ts',
    reverseRelation({
      fieldId: 'ONBOARDINGS_ON_MEMBER_ID',
      onObject: MEMBER,
      name: 'lvOnboardingsReviewed',
      label: 'Onboardings reviewed',
      icon: 'IconUserCheck',
      targetObject: ONBOARDING,
      targetField: 'ONBOARDING_REVIEWER_ID',
    }),
  ],
  [
    'src/modules/lv-onboarding/fields/documents-on-onboarding.field.ts',
    reverseRelation({
      fieldId: 'DOCS_ON_ONBOARDING_ID',
      onObject: ONBOARDING,
      name: 'documents',
      label: 'Documents',
      icon: 'IconFileCertificate',
      targetObject: ONBOARDING_DOC,
      targetField: 'DOC_ONBOARDING_ID',
    }),
  ],
  [
    'src/modules/lv-onboarding/fields/documents-on-member.field.ts',
    reverseRelation({
      fieldId: 'DOCS_ON_MEMBER_ID',
      onObject: MEMBER,
      name: 'lvDocumentsVerified',
      label: 'Documents verified',
      icon: 'IconShieldCheck',
      targetObject: ONBOARDING_DOC,
      targetField: 'DOC_REVIEWER_ID',
    }),
  ],
  // The task-side follow-up fields are hand-written in
  // src/modules/lv-followups/fields/ — they target a STANDARD object, which this
  // generator's targetObject shape does not express.

  // --- routing attributes on workspaceMember -------------------------------
  [
    'src/modules/lv-core/fields/member-regions.field.ts',
    scalarOnStandard({
      fieldId: 'MEMBER_REGIONS_FIELD_ID',
      name: 'lvRegions',
      label: 'Regions covered',
      icon: 'IconMapPin',
      type: 'ARRAY',
      description: 'Geographies this member handles, used for lead routing',
    }),
  ],
  [
    'src/modules/lv-core/fields/member-categories.field.ts',
    scalarOnStandard({
      fieldId: 'MEMBER_CATEGORIES_FIELD_ID',
      name: 'lvCategories',
      label: 'Categories covered',
      icon: 'IconCategory',
      type: 'ARRAY',
      description: 'Lead categories this member handles',
    }),
  ],
  [
    'src/modules/lv-core/fields/member-subcategories.field.ts',
    scalarOnStandard({
      fieldId: 'MEMBER_SUBCATEGORIES_FIELD_ID',
      name: 'lvExpertise',
      label: 'Expertise',
      icon: 'IconTags',
      type: 'ARRAY',
      description: 'Sub-categories this member has expertise in',
    }),
  ],
  [
    'src/modules/lv-core/fields/member-languages.field.ts',
    scalarOnStandard({
      fieldId: 'MEMBER_LANGUAGES_FIELD_ID',
      name: 'lvLanguages',
      label: 'Languages spoken',
      icon: 'IconLanguage',
      type: 'ARRAY',
      description: 'Languages this member can converse in',
    }),
  ],
  [
    'src/modules/lv-core/fields/member-lead-capacity.field.ts',
    scalarOnStandard({
      fieldId: 'MEMBER_LEAD_CAPACITY_FIELD_ID',
      name: 'lvLeadCapacity',
      label: 'Lead capacity',
      icon: 'IconGauge',
      type: 'NUMBER',
      description:
        'Maximum concurrent open leads. Zero pauses assignment without deactivating the member.',
    }),
  ],
  [
    'src/modules/lv-core/fields/member-accepts-leads.field.ts',
    scalarOnStandard({
      fieldId: 'MEMBER_ACCEPTS_LEADS_FIELD_ID',
      name: 'lvAcceptsLeads',
      label: 'Accepts leads',
      icon: 'IconUserCheck',
      type: 'BOOLEAN',
      description: 'Whether the assignment engine may route new leads here',
      // BOOLEAN takes a real boolean; the quoted-expression form is only for
      // TEXT defaults.
      extra: '\n  defaultValue: true,',
    }),
  ],
];

for (const [relativePath, contents] of files) {
  const target = path.join(ROOT, relativePath);

  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, contents, 'utf8');
}

process.stdout.write(`wrote ${files.length} field files\n`);
